head.script:
scwin.screenId = "jldfil05102";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name scwin.init_loadList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: reuse_tx). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_fn_documentWrite();
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_loadList();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil05102.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.grd_formPage_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_formPage_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_formPage');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_formPage'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (r["formCd"] === '70931') { if (typeof scwin.goWrite === 'function') { await scwin.goWrite(r["formCd"], r["formVer"], r["engFormCd"], r["engFormVer"], r["formAdmInstTpCd"], r["inqdisclsTpCd"], "0", r["formUpclssCd"], r["rsnClssCd"], r["applFormYn"], r["ldMktTpCd"]); } else { console.error('[sdd] 행 동작 미정의: scwin.goWrite (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.goWrite'); } return; }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_formPage.oncellclick' });
    }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_documentWrite
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_documentWrite = async function () {
    const sbmOptions = {
        id: "tx_fn_documentWrite",
        method: "post",
        action: "/submission/disclosure.do?method=searchDisclosureDocument",
        ref: "dma_documentWriteReq",
        target: "dlt_formPage=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil05102.tx_fn_documentWrite" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_fn_goWrite
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_goWrite = async function () {
    const sbmOptions = {
        id: "tx_fn_goWrite",
        method: "post",
        action: "/submission/disclosurereg.do?method=registerDisclosure",
        ref: "dma_goWriteReq",
        target: "dlt_formPage=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil05102.tx_fn_goWrite" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.documentWrite
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.documentWrite = async function () {
    /* sdd-asis-lifecycle:begin fn_documentWrite — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    (document.writeForm || { elements: [] }).action = '/submission/disclosure.do?method=searchDisclosureDocument';
    await scwin.tx_fn_documentWrite();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.registerProcess
 * @author Inswave
 * @date 2026. 09. 29
 * @param applNo docNo formCd formVer wrtrptMaindocTpCd method
 * @returns
 * @hidden N
*/
scwin.registerProcess = async function (applNo, docNo, formCd, formVer, wrtrptMaindocTpCd, method) {
    /* sdd-asis-lifecycle:begin fn_registerProcess — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('dma_documentWriteReq').set('applNo', applNo);
    if (applNo.length == 14) {
        await scwin.documentWrite();
    } else {
        await scwin.registerMessage('문서불러오기에 실패하였습니다. 잠시후 다시 해주시기 바랍니다.');
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.registerMessage
 * @author Inswave
 * @date 2026. 09. 29
 * @param msg
 * @returns
 * @hidden N
*/
scwin.registerMessage = async function (msg) {
    /* sdd-asis-lifecycle:begin registerMessage — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    await $c.win.alert(msg);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.goWrite
 * @author Inswave
 * @date 2026. 09. 29
 * @param formCd formVer engFormCd engFormVer formAdmInstTpCd inqdisclsTpCd langTpCd formUpclssCd rsnClssCd applFormYn ldMktTpCd
 * @returns
 * @hidden N
*/
scwin.goWrite = async function (formCd, formVer, engFormCd, engFormVer, formAdmInstTpCd, inqdisclsTpCd, langTpCd, formUpclssCd, rsnClssCd, applFormYn, ldMktTpCd) {
    /* sdd-asis-lifecycle:begin fn_goWrite — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('dma_documentWriteReq').set('disclsMaindocFormCd', formCd);
    $c.util.getComponent('dma_documentWriteReq').set('disclsMaindocFormVer', formVer);
    $c.util.getComponent('dma_documentWriteReq').set('formCd', formCd);
    $c.util.getComponent('dma_documentWriteReq').set('formVer', formVer);
    $c.util.getComponent('dma_documentWriteReq').set('langTpCd', langTpCd);
    $c.util.getComponent('dma_documentWriteReq').set('formUpclssCd', formUpclssCd);
    $c.util.getComponent('dma_documentWriteReq').set('rsnClssCd', rsnClssCd);
    $c.util.getComponent('dma_documentWriteReq').set('ldMktTpCd', ldMktTpCd);
    $c.util.getComponent('dma_documentWriteReq').set('disclsMaindocFormCd', formCd);
    $c.util.getComponent('dma_documentWriteReq').set('disclsMaindocFormVer', formVer);
    $c.util.getComponent('dma_documentWriteReq').set('formCd', formCd);
    $c.util.getComponent('dma_documentWriteReq').set('formVer', formVer);
    $c.util.getComponent('dma_documentWriteReq').set('langTpCd', langTpCd);
    $c.util.getComponent('dma_documentWriteReq').set('formUpclssCd', formUpclssCd);
    $c.util.getComponent('dma_documentWriteReq').set('rsnClssCd', rsnClssCd);
    $c.util.getComponent('dma_documentWriteReq').set('ldMktTpCd', ldMktTpCd);
    let acptApplTpCd = 'D';
    if (applFormYn === 'Y') {
        acptApplTpCd = 'L';
    }
    $c.util.getComponent('dma_documentWriteReq').set('acptApplTpCd', acptApplTpCd);
    $c.util.getComponent('dma_documentWriteReq').set('acptApplTpCd', acptApplTpCd);
    let engFormYn = 'N';
    if (langTpCd === '1') {
        engFormYn = 'Y';
    }
    $c.util.getComponent('dma_documentWriteReq').set('engFormYn', engFormYn);
    $c.util.getComponent('dma_documentWriteReq').set('engFormYn', engFormYn);
    (document.disclosureFrm || { elements: [] }).action = '/submission/disclosurereg.do?method=registerDisclosure';
    (document.disclosureFrm || { elements: [] }).target = 'tempSaveFrame';
    await scwin.tx_fn_goWrite();
    /* sdd-asis-lifecycle:end */
};
